130	    /**
131	     * getTransitionalState — Computes the full transitional topology from
132	     * GhostSplat field metrics and kernel diagnostics.
133	     */
134	    public getTransitionalState(
135	        field: GhostSplatField,
136	        diagnostics: KernelDiagnostics
137	    ): TransitionalState {
138	        const movingLines = this.detectMovingLines(field, diagnostics);
139	        const primaryHex = this.getCurrentHexagram();
140	        const futureHex = this.computeFutureHexagram(primaryHex, movingLines);
141	        const nuclearHex = this.computeNuclearHexagram(primaryHex);
142	
143	        return {
144	            primary: primaryHex,
145	            future: futureHex,
