154	    private detectMovingLines(
155	        field: GhostSplatField,
156	        diag: KernelDiagnostics
157	    ): MovingLine[] {
158	        const lines: MovingLine[] = [];
159	        const now = CanonicalClock.getInstance().simulatedNow();
160	
161	        // ── Line 1: Cache Substrate Health (internal) ──
162	        const cacheTime = diag.cacheParseTime || 0;
163	        const cacheTrend = diag.cacheParseTimeTrend || 0;
164	        if (cacheTime > LINE_THRESHOLDS[1].danger) {
165	            lines.push({ position: 1, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, cacheTime / 200), source: 'CacheForensicsLimb', timestamp: now });
166	        } else if (cacheTime < LINE_THRESHOLDS[1].recovery && cacheTrend < 0) {
167	            lines.push({ position: 1, fromState: 'YIN', toState: 'YANG', confidence: Math.min(1.0, Math.abs(cacheTrend)), source: 'CacheForensicsLimb', timestamp: now });
168	        }
169	
170	        // ── Line 2: NPC Prediction Confidence (intuitive) ──
171	        const npcConf = this.computeAvgConfidence(field.projections, 'npc_');
172	        if (npcConf < LINE_THRESHOLDS[2].danger) {
173	            lines.push({ position: 2, fromState: 'YANG', toState: 'YIN', confidence: 1.0 - npcConf, source: 'GhostSplatEngine', timestamp: now });
174	        } else if (npcConf > LINE_THRESHOLDS[2].recovery) {
175	            lines.push({ position: 2, fromState: 'YIN', toState: 'YANG', confidence: npcConf, source: 'GhostSplatEngine', timestamp: now });
176	        }
177	
178	        // ── Line 3: Combat Threat Density (conscious activity) ──
179	        const threatDensity = this.computeThreatDensity(field);
180	        if (threatDensity > LINE_THRESHOLDS[3].danger) {
181	            lines.push({ position: 3, fromState: 'YIN', toState: 'YANG', confidence: Math.min(1.0, threatDensity), source: 'CombatRotationEngine', timestamp: now });
182	        } else if (threatDensity < LINE_THRESHOLDS[3].recovery) {
183	            lines.push({ position: 3, fromState: 'YANG', toState: 'YIN', confidence: 1.0 - threatDensity, source: 'CombatRotationEngine', timestamp: now });
184	        }
185	
186	        // ── Line 4: Player Projection Drift (outer engagement) ──
187	        const playerDrift = this.computePlayerDrift(field);
188	        if (playerDrift > LINE_THRESHOLDS[4].danger) {
189	            lines.push({ position: 4, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, playerDrift / 5), source: 'PlayerAgent', timestamp: now });
190	        }
191	
192	        // ── Line 5: NecromancerBrain Prediction (mastery) ──
193	        const predTimeout = diag.necromancerLatency || 0;
194	        if (predTimeout > LINE_THRESHOLDS[5].danger) {
195	            lines.push({ position: 5, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, predTimeout / 1000), source: 'NecromancerBrain', timestamp: now });
196	        }
197	
198	        // ── Line 6: Tick Completion (culmination) ──
199	        const overrun = Math.max(0, (diag.lastTickDuration || 0) - 600);
200	        if (overrun > LINE_THRESHOLDS[6].danger) {
201	            lines.push({ position: 6, fromState: 'YANG', toState: 'YIN', confidence: Math.min(1.0, overrun / 200), source: 'TemporalHeartbeatLimb', timestamp: now });
202	        }
203	
204	        return lines;
205	    }
