207	    private computeAvgConfidence(projections: Map<string, EntityGhost>, prefix: string): number {
208	        let total = 0, count = 0;
209	        projections.forEach((ghost, id) => {
210	            if (id.startsWith(prefix)) {
211	                total += ghost.confidence;
212	                count++;
213	            }
214	        });
215	        return count > 0 ? total / count : 1.0;
216	    }
