218	    private computeThreatDensity(field: GhostSplatField): number {
219	        let hotTiles = 0;
220	        for (let i = 0; i < field.heatmap.length; i++) {
221	            if (field.heatmap[i] > 0) hotTiles++;
222	        }
223	        return hotTiles / (66 * 66);
224	    }
225	
226	    private computePlayerDrift(field: GhostSplatField): number {
227	        const playerGhost = Array.from(field.projections.values()).find(g => g.entityId.startsWith('player_'));
228	        if (!playerGhost) return 0;
229	        return playerGhost.confidence < 0.5 ? 5 : 0;
230	    }
231	
232	    private computeTransitionProgress(diag: KernelDiagnostics, movingLines: MovingLine[]): number {
233	        const tickElapsed = diag.tickElapsedMs || 0;
234	        const volatility = diag.volatilityEMA || 0;
