241	    private detectEnergyFlow(field: GhostSplatField): 'ASCENDING' | 'DESCENDING' | 'STABLE' {
242	        const centerHeat = this.sampleRegion(field.heatmap, 28, 28, 38, 38);
243	        const peripheryHeat = this.sampleRegion(field.heatmap, 0, 0, 66, 66) - centerHeat;
244	        const centerAvg = centerHeat / 100;
245	        const peripheryAvg = peripheryHeat / (66 * 66 - 100);
246	        if (peripheryAvg > centerAvg * 1.3) return 'ASCENDING';
247	        if (centerAvg > peripheryAvg * 1.3) return 'DESCENDING';
248	        return 'STABLE';
