251	    private sampleRegion(heatmap: Uint8Array, x1: number, y1: number, x2: number, y2: number): number {
252	        let sum = 0;
253	        for (let y = y1; y < y2; y++) {
254	            for (let x = x1; x < x2; x++) {
255	                sum += heatmap[y * 66 + x];
256	            }
257	        }
