1	// =============================================================================
2	// src/core/modeDetector.ts
3	// Intelligent Game Mode Inference Engine
4	// =============================================================================
5	
6	import { type ChatLine, type Buff } from '../utils/alt1Bridge';
7	
8	export type GameMode = 
9	  | 'combat-boss'      // Boss timer active, high HP target
10	  | 'combat-slayer'    // Slayer target, no boss timer
11	  | 'skilling-afk'     // XP dropping steadily, no target
12	  | 'skilling-active'  // XP dropping, interface open (herblore, etc)
13	  | 'ge-trading'       // GE interface detected
14	  | 'banking'          // Bank interface detected
15	  | 'clue-scroll'      // Clue interface or clue text in chat
16	  | 'quest-dialog'     // NPC dialog open
17	  | 'idle-lobby'       // No XP, no target, no interface
18	  | 'unknown';
19	
20	export interface TelemetrySnapshot {
21	  buffs: Buff[];
22	  debuffs: Buff[];
23	  target: { hp: number; name: string } | null;
24	  bossTimer: { minpart: number; secpart: number; time: number } | null;
25	  xpDrops: string[];
26	  chatLines: ChatLine[];
27	  tooltip: { text: string; area?: { x: number; y: number; width: number; height: number } } | null;
28	  dialog: { text: string[] | null; title: string } | null;
29	}
30	
31	export function detectGameMode(telemetry: TelemetrySnapshot): GameMode {
32	  // 1. Clue Scroll Mode
33	  const chatHasClue = telemetry.chatLines.some(l => 
34	    l.text.toLowerCase().includes('clue scroll') || 
35	    l.text.toLowerCase().includes('treasure scroll')
36	  );
37	  const tooltipHasClue = telemetry.tooltip?.text.toLowerCase().includes('clue scroll') || 
38	                         telemetry.tooltip?.text.toLowerCase().includes('casket');
39	  if (chatHasClue || tooltipHasClue) return 'clue-scroll';
40	
41	  // 2. NPC Dialog / Questing
42	  if (telemetry.dialog && telemetry.dialog.text && telemetry.dialog.text.length > 0) {
43	    return 'quest-dialog';
44	  }
45	
46	  // 3. Grand Exchange / Trading
47	  if (telemetry.tooltip?.text.toLowerCase().includes('grand exchange') || 
48	      telemetry.tooltip?.text.toLowerCase().includes('ge slot') ||
49	      telemetry.chatLines.some(l => l.text.toLowerCase().includes('grand exchange'))) {
50	    return 'ge-trading';
51	  }
52	
53	  // 4. Banking
54	  if (telemetry.tooltip?.text.toLowerCase().includes('bank') || 
55	      telemetry.tooltip?.text.toLowerCase().includes('withdraw') ||
56	      telemetry.tooltip?.text.toLowerCase().includes('deposit')) {
57	    return 'banking';
58	  }
59	
60	  // 5. Boss Combat
61	  if (telemetry.bossTimer && telemetry.bossTimer.time > 0) {
62	    return 'combat-boss';
63	  }
64	
65	  // 6. General Combat / Slayer
66	  if (telemetry.target && telemetry.target.hp > 0) {
67	    return 'combat-slayer';
68	  }
69	
70	  // 7. Active Skilling (XP counter moving, tooltip suggests interaction)
71	  const hasXp = telemetry.xpDrops.length > 0;
72	  if (hasXp) {
73	    // If tooltip suggests interface/actions
74	    const isInteractive = telemetry.tooltip?.text.match(/(use|craft|make|fletch|brew|cook|smelt)/i);
