3	// Complete bridge into the official Alt1 Toolkit (npm: alt1)
4	// Exposes ALL Alt1 sub-modules: base, chatbox, buffs, xpcounter, ocr,
5	// ability, bosstimer, dialog, dropsmenu, targetmob, tooltip
6	// =============================================================================
7	
8	import * as a1lib from 'alt1/base';
9	import ChatBoxReader, { type ChatLine, type Chatbox } from 'alt1/chatbox';
10	import BuffReader, { type Buff, type BuffTextTypes } from 'alt1/buffs';
11	import XpcounterReader from 'alt1/xpcounter';
12	import BossTimerReader from 'alt1/bosstimer';
