47	  if (!a1lib.hasAlt1) {
48	    return {
49	      available: false, version: null, skinName: 'browser',
50	      rsLinked: false, permissionPixel: false,
51	      permissionOverlay: false, permissionGameState: false,
52	    };
53	  }
