62	    permissionGameState: w.permissionGameState ?? false,
63	  };
64	}
65	
66	// ---------------------------------------------------------------------------
67	// 2. Screen Capture
68	// ---------------------------------------------------------------------------
69	
70	export function captureRegion(x: number, y: number, w: number, h: number): ImageData | null {
71	  if (!a1lib.hasAlt1) return null;
72	  try { return a1lib.capture(x, y, w, h); }
73	  catch { return null; }
74	}
