76	export async function captureRegionAsync(x: number, y: number, w: number, h: number): Promise<ImageData | null> {
77	  if (!a1lib.hasAlt1) return null;
78	  try { return await a1lib.captureAsync(x, y, w, h); }
79	  catch { return null; }
80	}
81	
82	export function captureFullClient() {
83	  if (!a1lib.hasAlt1) return null;
84	  try { return a1lib.captureHoldFullRs(); }
85	  catch { return null; }
86	}
87	
88	// ---------------------------------------------------------------------------
89	// 3. ChatBox Reader
90	// ---------------------------------------------------------------------------
91	
92	let _chatbox: ChatBoxReader | null = null;
93	
94	export function getChatboxReader(): ChatBoxReader {
95	  if (!_chatbox) _chatbox = new ChatBoxReader();
96	  return _chatbox;
97	}
98	
99	export function findChatbox(): boolean {
100	  if (!a1lib.hasAlt1) return false;
101	  return getChatboxReader().find() !== null;
102	}
103	
104	export function readChatLines(): ChatLine[] | null {
105	  if (!a1lib.hasAlt1) return null;
106	  const r = getChatboxReader();
107	  if (!r.pos) { if (!r.find()) return null; }
108	  return r.read();
109	}
110	
111	// ---------------------------------------------------------------------------
112	// 4. Buff / Debuff Reader
113	// ---------------------------------------------------------------------------
114	
115	let _buffs: BuffReader | null = null;
116	let _debuffs: BuffReader | null = null;
117	
118	export function readBuffs(): Buff[] | null {
119	  if (!a1lib.hasAlt1) return null;
120	  if (!_buffs) _buffs = new BuffReader();
121	  if (!_buffs.pos) { if (!_buffs.find()) return null; }
122	  return _buffs.read() ?? null;
123	}
124	
125	export function readDebuffs(): Buff[] | null {
126	  if (!a1lib.hasAlt1) return null;
127	  if (!_debuffs) { _debuffs = new BuffReader(); _debuffs.debuffs = true; }
128	  if (!_debuffs.pos) { if (!_debuffs.find()) return null; }
129	  return _debuffs.read() ?? null;
130	}
131	
132	// ---------------------------------------------------------------------------
133	// 5. XP Counter Reader
134	// ---------------------------------------------------------------------------
135	
136	let _xp: XpcounterReader | null = null;
137	
138	export function readXpCounter(): string[] | null {
139	  if (!a1lib.hasAlt1) return null;
140	  if (!_xp) _xp = new XpcounterReader();
141	  return _xp.readSkills() ?? null;
142	}
143	
144	// ---------------------------------------------------------------------------
145	// 6. Boss Timer Reader
146	// ---------------------------------------------------------------------------
147	
148	let _boss: BossTimerReader | null = null;
149	
150	export function readBossTimer(): { minpart: number; secpart: number; time: number } | null {
151	  if (!a1lib.hasAlt1) return null;
152	  if (!_boss) _boss = new BossTimerReader();
153	  if (!_boss.pos) { if (!_boss.find()) return null; }
154	  return _boss.read() ?? null;
155	}
