157	// ---------------------------------------------------------------------------
158	// 7. Target Mob Reader (enemy HP / name)
159	// ---------------------------------------------------------------------------
160	
161	let _target: TargetMobReader | null = null;
162	
163	export function readTargetMob(): { hp: number; name: string } | null {
164	  if (!a1lib.hasAlt1) return null;
165	  if (!_target) _target = new TargetMobReader();
166	  return _target.read() ?? null;
167	}
168	
169	// ---------------------------------------------------------------------------
170	// 8. Dialog Reader (NPC dialog & options)
171	// ---------------------------------------------------------------------------
172	
173	let _dialog: DialogReader | null = null;
174	
175	export function readDialog(): { text: string[] | null; opts: DialogButton[] | null; title: string } | null {
176	  if (!a1lib.hasAlt1) return null;
177	  if (!_dialog) _dialog = new DialogReader();
178	  if (!_dialog.pos) { if (!_dialog.find()) return null; }
179	  const result = _dialog.read();
180	  if (!result) return null;
181	  return result as { text: string[] | null; opts: DialogButton[] | null; title: string };
182	}
