184	// ---------------------------------------------------------------------------
185	// 9. Drops Menu Reader (loot beam / drop tracker)
186	// ---------------------------------------------------------------------------
187	
188	let _drops: DropsMenuReader | null = null;
189	
190	export function findDropsMenu(): boolean {
191	  if (!a1lib.hasAlt1) return false;
192	  if (!_drops) _drops = new DropsMenuReader();
193	  return _drops.find() !== null;
