/**
 * AudioLimb.ts
 * Sovereign Auditory Limb: TTS synthesis and alarm orchestration.
 * POG2 Domain: AUDIO (Auditory Cortex)
 */

import type { IAegisLimb, LimbStatus, LimbOutput, TelemetrySnapshot } from '../limb/Limb';
import { narrate, setNarratorVolume } from '../../core/voiceNarrator';

export class AudioLimb implements IAegisLimb {
  public readonly id = 'AUDITORY_CORTEX';
  public readonly domain = 'AUDIO';
  public status: LimbStatus = LimbStatus.ACTIVE;

  private volume: number = 70;

  constructor(initialVolume?: number) {
    if (initialVolume) this.setVolume(initialVolume);
  }

  public async pulse(telemetry: TelemetrySnapshot): Promise<LimbOutput | null> {
    // Auditory limb usually reacts to MotorLimb output, but can also trigger alarms
    // based on raw telemetry (e.g. "HP CRITICAL").
    if (telemetry.hp / telemetry.maxHp < 0.2) {
      return {
        payload: { event: 'Siren', text: 'HP CRITICAL' },
        confidence: 1.0,
        metabolicCost: 5,
        stage: 0,
        decision: 'EXECUTE'
      };
    }
    return null;
  }

  public async speak(text: string, priority: 'low' | 'medium' | 'high' | 'critical' = 'medium') {
    await narrate(text, priority);
  }

  public setVolume(vol: number) {
    this.volume = vol;
    setNarratorVolume(vol);
  }

  public async recalibrate(): Promise<void> {
    this.status = LimbStatus.ACTIVE;
  }
}

/**
 * MarketLimb.ts
 * Sovereign Market Limb: GE Flip analysis and arbitrage scoring.
 * POG2 Domain: FORGE (Market Intelligence)
 */

import type { IAegisLimb, LimbStatus, LimbOutput, TelemetrySnapshot } from '../limb/Limb';
import { analyzeFlip, type FlipAnalysis } from '../../utils/geEngine';
import { fetchGeItemDetail, fetchGePriceGraph, type JagexItemDetail } from '../../utils/geApi';

export interface TrackedItem {
  itemId: number;
  itemName: string;
  analysis: FlipAnalysis;
  alarmEnabled: boolean;
  alarmThreshold: number;
  alarmMode: 'below' | 'above';
  alarmSound: 'siren' | 'chime' | 'bell';
  lastTriggered: number;
}

export class MarketLimb implements IAegisLimb {
  public readonly id = 'MARKET_FORGE';
  public readonly domain = 'FORGE';
  public status: LimbStatus = LimbStatus.ACTIVE;

  private trackedItems: TrackedItem[] = [];

  constructor(initialItems: TrackedItem[] = []) {
    this.trackedItems = initialItems;
  }

  public async pulse(telemetry: TelemetrySnapshot): Promise<LimbOutput | null> {
    // In a real implementation, this would poll live prices for tracked items
    // and return a pulse if a price threshold is crossed.
    return null;
  }

  public async analyzeItem(itemId: number, itemName: string): Promise<LimbOutput> {
    const detail = await fetchGeItemDetail(itemId);
    const graph = await fetchGePriceGraph(itemId);

    if (detail && graph) {
      const analysis = analyzeFlip(detail.item, graph);
      return {
        payload: { analysis },
        confidence: 0.9,
        metabolicCost: 100,
        stage: 1, // Contextual retrieval
        decision: 'EXECUTE'
      };
    }

    return {
      payload: { error: 'Could not fetch item data' },
      confidence: 0,
      metabolicCost: 10,
      stage: 1,
      decision: 'DEFER'
    };
  }

  public addTrackedItem(item: TrackedItem) {
    this.trackedItems.push(item);
  }

  public getTrackedItems() {
    return this.trackedItems;
  }

  public async recalibrate(): Promise<void> {
    this.status = LimbStatus.ACTIVE;
  }
}

/**
 * MemoryLimb.ts
 * Sovereign Memory Limb: Handles session persistence and temporal pattern recognition.
 * POG2 Domain: MEMORY (Hippocampus)
 */

import type { IAegisLimb, LimbStatus, LimbOutput, TelemetrySnapshot } from '../limb/Limb';

interface SessionMemory {
  deaths: { bossName: string; timestamp: number }[];
  overloadsConsumed: { timestamp: number; doseDue: number }[];
  geTrades: { itemName: string; price: number; quantity: number; action: 'buy' | 'sell'; timestamp: number }[];
}

export class MemoryLimb implements IAegisLimb {
  public readonly id = 'HIPPOCAMPUS';
  public readonly domain = 'MEMORY';
  public status: LimbStatus = LimbStatus.ACTIVE;

  private memory: SessionMemory;

  constructor() {
    const raw = localStorage.getItem('aegis_session_memory');
    this.memory = raw ? JSON.parse(raw) : { deaths: [], overloadsConsumed: [], geTrades: [] };
  }

  public async pulse(telemetry: TelemetrySnapshot): Promise<LimbOutput | null> {
    // Detect death in chat or telemetry diffs
    const deathDetected = telemetry.chatLines.some(line => line.toLowerCase().includes('you died'));

    if (deathDetected) {
      const deathEntry = {
        bossName: telemetry.target?.name || 'Unknown',
        timestamp: Date.now()
      };
      this.memory.deaths.push(deathEntry);
      this.sync();

      return {
        payload: { event: 'DEATH_LOGGED', data: deathEntry },
        confidence: 1.0,
        metabolicCost: 1,
        stage: 0,
        decision: 'EXECUTE'
      };
    }

    return null;
  }

  public logTrade(trade: SessionMemory['geTrades'][number]) {
    this.memory.geTrades.push(trade);
    this.sync();
  }

  public logOverload(doseDue: number) {
    this.memory.overloadsConsumed.push({ timestamp: Date.now(), doseDue });
    this.sync();
  }

  private sync() {
    localStorage.setItem('aegis_session_memory', JSON.stringify(this.memory));
  }

  public async recalibrate(): Promise<void> {
    this.status = LimbStatus.ACTIVE;
  }

  public getState() {
    return this.memory;
  }
}

/**
 * MotorLimb.ts
 * Sovereign Motor Limb: Priority arbitration and AR command generation.
 * POG2 Domain: MOTOR (Motor Cortex)
 */

import type { IAegisLimb, LimbStatus, LimbOutput, TelemetrySnapshot } from '../limb/Limb';
import { generateGuidance } from '../../core/guidanceEngine';
import { renderClickGuide } from '../../utils/clickGuide';

export class MotorLimb implements IAegisLimb {
  public readonly id = 'MOTOR_CORTEX';
  public readonly domain = 'MOTOR';
  public status: LimbStatus = LimbStatus.ACTIVE;

  public async pulse(telemetry: TelemetrySnapshot): Promise<LimbOutput | null> {
    const mode = (this as any).thalamus?.getLimb('SENSORY').getCurrentMode() || 'unknown';
    const guidance = generateGuidance(mode, telemetry, null);

    if (guidance) {
      // Check for critical threats first (POG2 Priority Matrix)
      const isCritical = telemetry.target?.hp ? (telemetry.target.hp / 100 < 0.4) : false;

      return {
        payload: {
          text: guidance.speak,
          urgency: guidance.priority === 'critical' ? 'CRITICAL' : 'NORMAL',
          clickTarget: this.calculateClickTarget(guidance.speak)
        },
        confidence: 0.9,
        metabolicCost: 10,
        stage: 0,
        decision: 'EXECUTE'
      };
    }

    return null;
  }

  private calculateClickTarget(guidance: string): any | null {
    // Simple keyword-to-coord mapping for the prototype
    if (guidance.includes('Eat')) return { x: 1200, y: 900, label: 'Food' };
    if (guidance.includes('Restore')) return { x: 1200, y: 850, label: 'Prayer Pot' };
    return null;
  }

  public async recalibrate(): Promise<void> {
    this.status = LimbStatus.ACTIVE;
  }
}

/**
 * OracleLimb.ts
 * Sovereign Oracle Limb: LLM prompt engineering and response parsing.
 * POG2 Domain: LITERARY (Oracle Cortex)
 */

import type { IAegisLimb, LimbStatus, LimbOutput, TelemetrySnapshot } from '../limb/Limb';
import { askLocalOracle } from '../../utils/ollamaBridge';

export class OracleLimb implements IAegisLimb {
  public readonly id = 'ORACLE_CORTEX';
  public readonly domain = 'LITERARY';
  public status: LimbStatus = LimbStatus.ACTIVE;

  private aiMode: 'gemini' | 'ollama' = 'gemini';
  private ollamaModel: string = 'moondream';

  constructor(mode?: 'gemini' | 'ollama', model?: string) {
    this.aiMode = mode || 'gemini';
    this.ollamaModel = model || 'moondream';
  }

  public async pulse(telemetry: TelemetrySnapshot): Promise<LimbOutput | null> {
    // The Oracle usually doesn't pulse autonomously unless prompted by a la "ambient loop"
    // This is where the "Siri-like" proactive guidance would be triggered.
    return null;
  }

  public async query(prompt: string, telemetry: TelemetrySnapshot): Promise<LimbOutput> {
    if (this.aiMode === 'ollama') {
      try {
        const response = await askLocalOracle(
          '', // base64Snapshot would go here
          prompt,
          this.ollamaModel
        );

        return {
          payload: { text: response },
          confidence: 0.8,
          metabolicCost: 500,
          stage: 2, // Local AI
          decision: 'EXECUTE'
        };
      } catch (e) {
        this.status = LimbStatus.ERROR;
        return {
          payload: { error: 'Local Oracle unavailable' },
          confidence: 0,
          metabolicCost: 10,
          stage: 2,
          decision: 'DEFER'
        };
      }
    }

    // Gemini implementation would follow a similar pattern (Stage 4)
    return {
      payload: { text: 'Gemini integration pending' },
      confidence: 0.5,
      metabolicCost: 2000,
      stage: 4,
      decision: 'DEFER'
    };
  }

  public setMode(mode: 'gemini' | 'ollama') {
    this.aiMode = mode;
  }

  public setModel(model: string) {
    this.ollamaModel = model;
  }

  public async recalibrate(): Promise<void> {
    this.status = LimbStatus.ACTIVE;
  }
}
